import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext();

export function AuthProvider({ children, apiBase }) {
  const [currentUser, setCurrentUser] = useState(null);
  const [demoUsers, setDemoUsers] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch demo users on mount
  useEffect(() => {
    fetch(`${apiBase}/api/v1/demo-users`)
      .then((res) => res.json())
      .then((data) => {
        setDemoUsers(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Failed to load demo users:", err);
        setLoading(false);
      });
  }, [apiBase]);

  const login = (user) => setCurrentUser(user);
  const logout = () => setCurrentUser(null);

  // Helper for authenticated fetch
  const authFetch = (endpoint, options = {}) => {
    const headers = { ...options.headers };

    // Only set application/json if body is not FormData
    if (!(options.body instanceof FormData)) {
      headers['Content-Type'] = headers['Content-Type'] || 'application/json';
    }

    if (currentUser) {
      headers['X-User-ID'] = currentUser.id;
    }
    return fetch(`${apiBase}${endpoint}`, { ...options, headers });
  };

  return (
    <AuthContext.Provider value={{ currentUser, demoUsers, loading, login, logout, authFetch }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
